import {architects} from './data.js';
import {BuildingViewer} from './models.js';
const $=s=>document.querySelector(s);
let index=0,tab='ideas',viewer,credits={};
try{viewer=new BuildingViewer($('#model-viewer'));}catch(e){$('#model-loading').innerHTML='この環境では3D表示を開始できません。<br>解説と資料は引き続きお読みいただけます。';console.error(e);}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function makeNav(){let last='';$('#architect-list').innerHTML=architects.map((a,i)=>{const heading=a.era!==last?`<div class="era-heading">${a.era}</div>`:'';last=a.era;return heading+`<button class="architect-item" data-id="${a.id}" aria-current="false"><span class="nav-index">${String(i+1).padStart(2,'0')}</span><span class="nav-name">${a.short}<small>${a.life}</small></span></button>`;}).join('');$('#count').textContent=String(architects.length).padStart(2,'0');$('#architect-list').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b)location.hash=b.dataset.id;});}
function renderProfile(){const a=architects[index],c=credits[a.id];$('#profile').innerHTML=`${c?`<img class="portrait" src="${esc(c.path)}" style="object-position:${esc(c.objectPosition)}" alt="${esc(a.name)}${a.id==='sinan'?'と考えられる人物像':'の肖像'}" width="84" height="105">`:''}<div><p class="life">${a.life}</p><p class="region">${a.region}</p><span class="style-label">${a.style}</span>${a.id==='sinan'?'<p class="portrait-qualifier">肖像はシナンと考えられる人物像</p>':''}</div>`;}
function renderStory(){const a=architects[index];for(const b of document.querySelectorAll('[data-tab]')){const active=b.dataset.tab===tab;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1;}$('#story-content').setAttribute('aria-labelledby','tab-'+tab);if(tab==='ideas'){$('#story-content').innerHTML=`<h2 class="thesis">${a.thesis}</h2><p class="story-copy">${a.intro}</p>${a.ideas.map(([title,copy])=>`<section class="story-block"><h3>${title}</h3><p class="story-copy">${copy}</p></section>`).join('')}<div class="takeaway"><span class="eyebrow">この建築家から学ぶこと</span><p>${a.takeaway}</p></div>`;}else if(tab==='building'){$('#story-content').innerHTML=`<h2 class="thesis">${a.work.name}</h2><p class="story-copy">${a.work.description}</p>${a.work.collaboration?`<p class="credit">${a.work.collaboration}</p>`:''}${a.work.highlights.map(([title,copy],i)=>`<section class="story-block"><h3>${String(i+1).padStart(2,'0')}　${title}</h3><p class="story-copy">${copy}</p></section>`).join('')}<section class="story-block"><h3>ほかの代表作・関連作品</h3><ul class="work-list">${a.works.map(([date,title])=>`<li><span>${date}</span>${title}</li>`).join('')}</ul></section>`;}else{const c=credits[a.id];$('#story-content').innerHTML=`<h2 class="thesis">もっと深く知る。</h2><p class="credit">解説は以下の施設・財団などの公開資料をもとに編集しています。リンク先は別のタブで開きます。</p><ol class="source-list">${a.sources.map(([name,url])=>`<li><a href="${url}" target="_blank" rel="noopener noreferrer">${name} ↗</a></li>`).join('')}</ol><section class="story-block"><h3>肖像のクレジット</h3>${c?`<p class="credit">${esc(c.creator)}<br><a href="${esc(c.sourceUrl)}" target="_blank" rel="noopener noreferrer">画像の出典 ↗</a> · <a href="${esc(c.licenseUrl||c.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(c.license)}</a><br>${esc(c.note||'')}<br>画面上ではモノクロ表示・トリミングをしています。</p>`:'<p class="credit">肖像の出典を準備しています。</p>'}</section><section class="story-block"><h3>3Dモデルについて</h3><p class="credit">当アトラス独自制作の概念模型。${a.work.note} 寸法・材質・比例は説明のための近似です。</p></section>`;}}
function select(){const id=location.hash.slice(1);index=Math.max(0,architects.findIndex(a=>a.id===id));const a=architects[index];$('#architect-name').textContent=a.name;$('#architect-english').textContent=a.english;$('#era-label').textContent=`${a.era}　/　${a.period}`;$('#exhibit-number').innerHTML=`${String(index+1).padStart(2,'0')} <small>/ ${String(architects.length).padStart(2,'0')}</small>`;$('#work-name').textContent=a.work.name;$('#work-date').textContent=`${a.work.date}　/　${a.work.english.toUpperCase()}`;$('#work-place').textContent=a.work.place;$('#model-note').textContent=`模型について：${a.work.note}`;$('#model-viewer').setAttribute('aria-label',`${a.work.name}の3D概念模型。ドラッグまたは矢印キーで回転できます。`);$('#model-highlights').innerHTML=a.work.highlights.map(([title],i)=>`<button class="highlight" data-focus="${i}" aria-pressed="false"><span>${String(i+1).padStart(2,'0')}</span>${title}</button>`).join('');document.querySelectorAll('[data-id]').forEach(b=>b.setAttribute('aria-current',b.dataset.id===a.id));$('#previous').disabled=index===0;$('#next').disabled=index===architects.length-1;$('#next').innerHTML=index===architects.length-1?'最後の建築家':`${architects[index+1].short} <span>→</span>`;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.view==='perspective'));$('#rotate').setAttribute('aria-pressed','false');$('#wireframe').setAttribute('aria-pressed','false');renderProfile();renderStory();viewer?.load(a.id);if(matchMedia('(max-width:650px)').matches){const selectedButton=document.querySelector('[data-id="'+a.id+'"]');const nav=document.querySelector('#architect-list');nav.scrollLeft=selectedButton.offsetLeft-nav.clientWidth/2+selectedButton.clientWidth/2;}if(!viewer)document.querySelectorAll('.highlight').forEach(b=>b.disabled=true);document.title=`${a.name} | 建築の系譜`;}
makeNav();window.addEventListener('hashchange',()=>{if(location.hash==='#main')return;select();window.scrollTo({top:0,behavior:'instant'});});if(!location.hash)history.replaceState(null,'','#corbusier');select();
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();};
fetch('./portraits.json').then(r=>r.ok?r.json():{}).then(data=>{credits=data;renderProfile();if(tab==='sources')renderStory();}).catch(()=>{});
$('.story-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b){tab=b.dataset.tab;renderStory();}});
$('.story-tabs').addEventListener('keydown',e=>{const tabs=[...document.querySelectorAll('[data-tab]')];const i=tabs.indexOf(document.activeElement);if(i<0)return;let next;if(e.key==='ArrowRight')next=(i+1)%3;if(e.key==='ArrowLeft')next=(i+2)%3;if(e.key==='Home')next=0;if(e.key==='End')next=2;if(next!==undefined){e.preventDefault();tab=tabs[next].dataset.tab;renderStory();tabs[next].focus();}});
$('.view-presets').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(!b)return;viewer?.view(b.dataset.view);document.querySelectorAll('[data-view]').forEach(n=>n.setAttribute('aria-pressed',n===b));});
$('#rotate').onclick=()=>{const on=$('#rotate').getAttribute('aria-pressed')!=='true';$('#rotate').setAttribute('aria-pressed',on);if(viewer)viewer.controls.autoRotate=on;};
$('#wireframe').onclick=()=>{const on=$('#wireframe').getAttribute('aria-pressed')!=='true';$('#wireframe').setAttribute('aria-pressed',on);viewer?.wire(on);};
$('#reset').onclick=()=>{viewer?.view('perspective');document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.view==='perspective'));};
$('#model-highlights').onclick=e=>{const b=e.target.closest('[data-focus]');if(!b)return;document.querySelectorAll('[data-focus]').forEach(n=>n.setAttribute('aria-pressed',n===b));viewer?.focus(Number(b.dataset.focus));tab='building';renderStory();};
$('#previous').onclick=()=>{if(index>0)location.hash=architects[index-1].id;};$('#next').onclick=()=>{if(index<architects.length-1)location.hash=architects[index+1].id;};
$('#about-open').onclick=()=>$('#about-dialog').showModal();$('#about-close').onclick=()=>$('#about-dialog').close();$('#about-dialog').addEventListener('click',e=>{if(e.target===$('#about-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function stopAutoRotate(){if(viewer)viewer.controls.autoRotate=false;$('#rotate').setAttribute('aria-pressed','false');}
$('.view-presets').addEventListener('click',stopAutoRotate);$('#reset').addEventListener('click',()=>{stopAutoRotate();viewer?.wire(false);$('#wireframe').setAttribute('aria-pressed','false');document.querySelectorAll('[data-focus]').forEach(b=>b.setAttribute('aria-pressed','false'));});
$('#model-highlights').addEventListener('click',()=>{stopAutoRotate();document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed','false'));});
if(!viewer)document.querySelectorAll('.viewer-tools button,.highlight').forEach(b=>b.disabled=true);
const modelContext=document.modelContext||navigator.modelContext;
if(modelContext?.registerTool){
 const toolDefinitions=[
  {name:'list_architects',description:'List the 12 architects, their representative buildings and the current selection in this architecture-history atlas.',inputSchema:{type:'object',properties:{}},execute:async()=>JSON.stringify({current:architects[index].id,architects:architects.map(a=>({id:a.id,name:a.name,era:a.era,building:a.work.name}))})},
  {name:'explore_architect',description:'Open an architect and choose the Japanese explanation: ideas, building, or sources. Changes only this page view.',inputSchema:{type:'object',properties:{id:{type:'string',enum:architects.map(a=>a.id)},section:{type:'string',enum:['ideas','building','sources']}},required:['id']},execute:async({id,section='ideas'})=>{if(!architects.some(a=>a.id===id)||!['ideas','building','sources'].includes(section))throw Error('Invalid architect or section');tab=section;history.pushState(null,'','#'+id);select();window.scrollTo({top:0,behavior:'instant'});return `${architects[index].name} — ${section}`;}},
  {name:'set_building_view',description:'Change the active 3D conceptual building model to perspective, front, or top view.',inputSchema:{type:'object',properties:{view:{type:'string',enum:['perspective','front','top']}},required:['view']},execute:async({view})=>{if(!['perspective','front','top'].includes(view))throw Error('Invalid view');if(!viewer)throw Error('WebGL is unavailable');document.querySelector(`[data-view="${view}"]`).click();return `${architects[index].work.name}: ${view}`;}}
 ];
 for(const tool of toolDefinitions){try{Promise.resolve(modelContext.registerTool(tool)).catch(()=>{});}catch{}}
}

